"""核心运算与表达式求值模块。

仅使用标准库 ast 进行安全解析，不使用 eval。
"""

from __future__ import annotations

import ast
from typing import Union

Number = Union[int, float]


class CalcError(Exception):
    """计算器基础异常。"""


class DivisionByZeroError(CalcError):
    """除零异常。"""


class InvalidExpressionError(CalcError):
    """表达式语法或结构非法。"""


class UnsupportedSyntaxError(CalcError):
    """表达式包含不支持的语法节点。"""


def _to_number(value: object, raw: object = None) -> float:
    """将输入转换为 float，失败时抛出 InvalidExpressionError。"""
    if isinstance(value, bool):
        raise InvalidExpressionError(f"invalid number: {raw if raw is not None else value}")
    if isinstance(value, (int, float)):
        return float(value)
    try:
        return float(value)  # type: ignore[arg-type]
    except (TypeError, ValueError):
        raise InvalidExpressionError(
            f"invalid number: {raw if raw is not None else value}"
        ) from None


def add(a: Number, b: Number) -> float:
    """加法。"""
    return _to_number(a) + _to_number(b)


def sub(a: Number, b: Number) -> float:
    """减法。"""
    return _to_number(a) - _to_number(b)


def mul(a: Number, b: Number) -> float:
    """乘法。"""
    return _to_number(a) * _to_number(b)


def div(a: Number, b: Number) -> float:
    """除法；除数为零时抛出 DivisionByZeroError。"""
    numerator = _to_number(a)
    denominator = _to_number(b)
    if denominator == 0:
        raise DivisionByZeroError("division by zero")
    return numerator / denominator


_BIN_OPS = {
    ast.Add: add,
    ast.Sub: sub,
    ast.Mult: mul,
    ast.Div: div,
}

_UNARY_OPS = {
    ast.UAdd: lambda v: +v,
    ast.USub: lambda v: -v,
}


def _eval_node(node: ast.AST) -> float:
    if isinstance(node, ast.Expression):
        return _eval_node(node.body)
    if isinstance(node, ast.Constant):
        if isinstance(node.value, bool) or not isinstance(node.value, (int, float)):
            raise UnsupportedSyntaxError(f"unsupported syntax: {type(node).__name__}")
        return float(node.value)
    if isinstance(node, ast.BinOp):
        op_type = type(node.op)
        if op_type not in _BIN_OPS:
            raise UnsupportedSyntaxError(f"unsupported syntax: {op_type.__name__}")
        left = _eval_node(node.left)
        right = _eval_node(node.right)
        return _BIN_OPS[op_type](left, right)
    if isinstance(node, ast.UnaryOp):
        op_type = type(node.op)
        if op_type not in _UNARY_OPS:
            raise UnsupportedSyntaxError(f"unsupported syntax: {op_type.__name__}")
        return _UNARY_OPS[op_type](_eval_node(node.operand))
    raise UnsupportedSyntaxError(f"unsupported syntax: {type(node).__name__}")


def evaluate(expression: str) -> float:
    """解析并求值表达式字符串。

    抛出 InvalidExpressionError / UnsupportedSyntaxError / DivisionByZeroError。
    """
    if not isinstance(expression, str) or not expression.strip():
        raise InvalidExpressionError(f"invalid expression: {expression!r}")
    try:
        tree = ast.parse(expression, mode="eval")
    except SyntaxError:
        raise InvalidExpressionError(f"invalid expression: {expression}") from None
    return _eval_node(tree)


def format_result(value: float) -> str:
    """将结果格式化为输出字符串（整数去尾 .0）。"""
    number = _to_number(value)
    if number == int(number):
        return str(int(number))
    return repr(number)

"""命令行入口与参数解析模块。"""

from __future__ import annotations

import argparse
import sys
from typing import Optional, Sequence

from .core import (
    CalcError,
    DivisionByZeroError,
    InvalidExpressionError,
    UnsupportedSyntaxError,
    add,
    div,
    evaluate,
    format_result,
    mul,
    sub,
)

_OPS = {
    "add": add,
    "sub": sub,
    "mul": mul,
    "div": div,
}


def build_parser() -> argparse.ArgumentParser:
    """构建命令行参数解析器。"""
    parser = argparse.ArgumentParser(
        prog="calc",
        description="命令行计算器：支持加、减、乘、除。",
    )
    parser.add_argument(
        "expression",
        nargs="?",
        help="表达式字符串，例如 \"1 + 2 * 3\"。",
    )
    parser.add_argument(
        "--op",
        choices=sorted(_OPS.keys()),
        help="运算符模式：add/sub/mul/div，需配合两个操作数。",
    )
    parser.add_argument(
        "operands",
        nargs="*",
        help="当使用 --op 时提供的两个操作数。",
    )
    return parser


def _parse_number(raw: str) -> float:
    try:
        return float(raw)
    except (TypeError, ValueError):
        raise InvalidExpressionError(f"invalid number: {raw}") from None


def _run(args: argparse.Namespace) -> float:
    if args.op is not None:
        if len(args.operands) != 2:
            raise InvalidExpressionError(
                "--op requires exactly two operands"
            )
        a = _parse_number(args.operands[0])
        b = _parse_number(args.operands[1])
        return _OPS[args.op](a, b)
    if args.expression is None:
        raise InvalidExpressionError("no expression provided")
    return evaluate(args.expression)


def main(argv: Optional[Sequence[str]] = None) -> int:
    """命令行入口，返回进程退出码。"""
    parser = build_parser()
    args = parser.parse_args(argv)
    try:
        result = _run(args)
    except DivisionByZeroError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1
    except UnsupportedSyntaxError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1
    except InvalidExpressionError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1
    except CalcError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1
    print(format_result(result))
    return 0


if __name__ == "__main__":
    sys.exit(main())

"""Pure calculation core: no I/O, no argument parsing.

All functions here are side-effect free and raise typed exceptions
so that callers (CLI, tests, future APIs) can handle errors uniformly.
"""

from __future__ import annotations

from typing import Callable, Dict


class CalculationError(Exception):
    """Base class for all calculation related errors."""


class InvalidOperandError(CalculationError):
    """Raised when an operand cannot be parsed as a number."""


class UnsupportedOperatorError(CalculationError):
    """Raised when the operator is not registered."""


class DivisionByZeroError(CalculationError):
    """Raised when dividing by zero."""


Operation = Callable[[float, float], float]

OPERATIONS: Dict[str, Operation] = {}


def register_operation(symbol: str, func: Operation) -> None:
    """Register a binary operation under the given symbol."""
    if not isinstance(symbol, str) or not symbol:
        raise ValueError("operator symbol must be a non-empty string")
    if not callable(func):
        raise ValueError("operation must be callable")
    OPERATIONS[symbol] = func


def _add(a: float, b: float) -> float:
    return a + b


def _sub(a: float, b: float) -> float:
    return a - b


def _mul(a: float, b: float) -> float:
    return a * b


def _div(a: float, b: float) -> float:
    if b == 0:
        raise DivisionByZeroError("division by zero is not allowed")
    return a / b


register_operation("+", _add)
register_operation("-", _sub)
register_operation("*", _mul)
register_operation("/", _div)


def parse_operand(raw: str) -> float:
    """Parse a raw string into a float, raising InvalidOperandError on failure."""
    if raw is None:
        raise InvalidOperandError("operand is missing")
    text = str(raw).strip()
    if not text:
        raise InvalidOperandError("operand is empty")
    try:
        return float(text)
    except (TypeError, ValueError) as exc:
        raise InvalidOperandError(f"invalid operand: {raw!r}") from exc


def calculate(a: float, operator: str, b: float) -> float:
    """Apply the registered operation for `operator` to a and b.

    Raises UnsupportedOperatorError for unknown operators and
    DivisionByZeroError when dividing by zero.
    """
    if operator not in OPERATIONS:
        raise UnsupportedOperatorError(f"unsupported operator: {operator!r}")
    return OPERATIONS[operator](a, b)

"""Command line interface for calc.

The CLI only parses arguments and formats output; all math lives in core.

Supported forms:
    calc 1 + 2
    calc 1 + 2 --json
    calc --expr "1 + 2"
"""

from __future__ import annotations

import argparse
import json
import sys
from typing import List, Optional

from .core import (
    CalculationError,
    calculate,
    parse_operand,
)


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="calc",
        description="A simple command line calculator supporting + - * /",
    )
    parser.add_argument("operands", nargs="*", help="<a> <operator> <b>")
    parser.add_argument(
        "--expr",
        default=None,
        help="expression form, e.g. --expr \"1 + 2\"",
    )
    parser.add_argument(
        "--json",
        action="store_true",
        help="print the result as JSON",
    )
    return parser


def _tokens_from_args(args: argparse.Namespace) -> List[str]:
    if args.expr is not None:
        if args.operands:
            raise CalculationError("use either positional operands or --expr, not both")
        return args.expr.split()
    return list(args.operands)


def run(argv: Optional[List[str]] = None) -> int:
    parser = build_parser()
    args = parser.parse_args(argv)

    try:
        tokens = _tokens_from_args(args)
        if len(tokens) != 3:
            raise CalculationError(
                "expected exactly three tokens: <a> <operator> <b>"
            )
        left = parse_operand(tokens[0])
        operator = tokens[1]
        right = parse_operand(tokens[2])
        result = calculate(left, operator, right)
    except CalculationError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 2

    if args.json:
        print(json.dumps({"a": left, "operator": operator, "b": right, "result": result}))
    else:
        print(result)
    return 0


def main() -> None:
    raise SystemExit(run())


if __name__ == "__main__":
    main()

import math

import pytest

from calc.core import (
    CalculationError,
    DivisionByZeroError,
    InvalidOperandError,
    UnsupportedOperatorError,
    calculate,
    parse_operand,
    register_operation,
)


@pytest.mark.parametrize(
    "a,op,b,expected",
    [
        (1, "+", 2, 3),
        (-1, "+", 1, 0),
        (0, "+", 0, 0),
        (5, "-", 3, 2),
        (3, "-", 5, -2),
        (2, "*", 3, 6),
        (-2, "*", 3, -6),
        (0, "*", 100, 0),
        (6, "/", 3, 2),
        (1, "/", 4, 0.25),
        (-6, "/", 3, -2),
    ],
)
def test_calculate_basic(a, op, b, expected):
    assert calculate(a, op, b) == pytest.approx(expected)


@pytest.mark.parametrize("a,b", [(1, 0), (0, 0), (-1, 0), (1.5, 0.0)])
def test_division_by_zero(a, b):
    with pytest.raises(DivisionByZeroError):
        calculate(a, "/", b)


def test_division_by_zero_is_calculation_error():
    assert issubclass(DivisionByZeroError, CalculationError)


@pytest.mark.parametrize("op", ["%", "^", "", "++", "add"])
def test_unsupported_operator(op):
    with pytest.raises(UnsupportedOperatorError):
        calculate(1, op, 2)


@pytest.mark.parametrize("raw,expected", [("1", 1.0), (" 2.5 ", 2.5), ("-3", -3.0), ("1e3", 1000.0)])
def test_parse_operand_ok(raw, expected):
    assert parse_operand(raw) == pytest.approx(expected)


@pytest.mark.parametrize("raw", ["", "   ", "abc", "1,2", None, "--"])
def test_parse_operand_invalid(raw):
    with pytest.raises(InvalidOperandError):
        parse_operand(raw)


def test_register_operation_extends_registry():
    register_operation("**", lambda a, b: a ** b)
    try:
        assert calculate(2, "**", 10) == pytest.approx(1024)
    finally:
        from calc.core import OPERATIONS

        OPERATIONS.pop("**", None)


def test_register_operation_rejects_bad_input():
    with pytest.raises(ValueError):
        register_operation("", lambda a, b: a)
    with pytest.raises(ValueError):
        register_operation("@", "not-callable")


def test_float_precision_is_reasonable():
    assert math.isclose(calculate(0.1, "+", 0.2), 0.3, rel_tol=1e-9)
